diff --git a/crates/turts_rules/src/damage.rs b/crates/turts_rules/src/damage.rs
index 101a127..b3c6784 100644
--- a/crates/turts_rules/src/damage.rs
+++ b/crates/turts_rules/src/damage.rs
@@ -19,3 +19,3 @@ pub fn base(weapon_damage: u64, modifier: u64) -> Option<u64> {
 pub fn raw(base: u64, cell: Ratio) -> u64 {
-    saturate_u64(mul_div_u64(base, cell.numerator(), cell.denominator()))
+    (base as f64 * (cell.numerator() as f64 / cell.denominator() as f64)).floor() as u64
 }

