@@ -26,3 +26,3 @@ pub fn raw(base: u64, cell: Ratio) -> u64 {
 pub fn hit(base: u64, cell: Ratio, minimum: u64, flat_armour: u64) -> u64 {
-    minimum.max(raw(base, cell).saturating_sub(flat_armour))
