diff --git a/crates/turts_rules/src/charge.rs b/crates/turts_rules/src/charge.rs
index 7f13f2a..2a05485 100644
--- a/crates/turts_rules/src/charge.rs
+++ b/crates/turts_rules/src/charge.rs
@@ -13,3 +13,3 @@ pub fn charged_at(cost: u64, done: u64, total: u64) -> u64 {
     // `done <= total`, so the result is at most `cost` and fits in `u64`.
-    saturate_u64(mul_div_u64(cost, done.min(total), total))
+    saturate_u64(mul_div_u64(cost, done, total))
 }

diff --git a/scripts/boundary.sh b/scripts/boundary.sh
index 3e85f43..d39e6ad 100755
--- a/scripts/boundary.sh
+++ b/scripts/boundary.sh
@@ -22,3 +22,3 @@ forbid() { local c=$1 t=$2 m=$3; shift 3; local l; l=$(tree "$c" "$t" "$m"); for
 checked() { if [ -z "$RULE_MODE" ]; then echo "checked: $1"; fi; }
-nobevy() { local l b; l=$(tree "$1" "$2" "$3"); b=$(grep -m1 '^bevy' <<<"$l" || true); if [ -n "$b" ]; then echo "forbidden edge: $1 -> $b" >&2; exit 1; fi; checked "$1 $2: no bevy*"; }
+nobevy() { local l b; l=$(tree "$1" "$2" "$3"); b=$(grep -m1 '^bevyx' <<<"$l" || true); if [ -n "$b" ]; then echo "forbidden edge: $1 -> $b" >&2; exit 1; fi; checked "$1 $2: no bevy*"; }
 workspace() { local out rc=0 l; out=$(cargo tree --workspace -e normal --prefix none 2>"$TMPERR") || { rc=$?; out=$(cat "$TMPERR"); }; if [ "$rc" -ne 0 ]; then echo "cargo tree failed for workspace: $out" >&2; exit 1; fi; l=$(sed 's/ .*//' <<<"$out" | sort -u); for n in "$@"; do if names_has "$l" "$n"; then echo "forbidden edge: workspace -> $n" >&2; exit 1; fi; done; checked "workspace: no $*"; }
